5: private val libraryStartupTabs = setOf("LIBRARY", "SONGS", "TRACKS", "FAVORITES", "ARTISTS", "ALBUMS", "PLAYLISTS")
6: 
7: fun defaultOpenTabRoot(current: String): String =
8:     when (current) {
9:         "SEARCH" -> "SEARCH"
10:         in libraryStartupTabs -> "LIBRARY"
11:         else -> "HOME"
12:     }
13: 
14: fun defaultOpenTabScreen(current: String): Screen =
15:     when (current) {
16:         "FAVORITES" -> {
17:             Screen.AutoPlaylist("liked")
18:         }
19: 
20:         "MYSTERIOUS" -> {
21:             Screen.EasterEgg
22:         }
23: 
24:         else -> {
25:             when (defaultOpenTabRoot(current)) {
26:                 "SEARCH" -> Screen.Search
27:                 "LIBRARY" -> Screen.Library
28:                 else -> Screen.Home
29:             }
30:         }
31:     }
32: 
33: fun normalizeDefaultOpenTab(
34:     current: String,
35:     showHome: Boolean,
36:     showSearch: Boolean,
37:     showLibrary: Boolean,
38: ): String {
39:     val tab = current.takeUnless { it == "SONGS" } ?: "LIBRARY"
40:     val currentCategory =
41:         when (tab) {
42:             "HOME" -> 0
43:             "SEARCH" -> 1
44:             in libraryStartupTabs -> 2
45:             else -> -1
46:         }
47:     val visible = listOf(showHome, showSearch, showLibrary)
48:     if (currentCategory in visible.indices && visible[currentCategory]) return tab
49: 
50:     repeat(visible.size) { offset ->
51:         val index = (currentCategory + offset + 1).mod(visible.size)
52:         if (visible[index]) {
53:             return when (index) {
54:                 0 -> "HOME"
55:                 1 -> "SEARCH"
56:                 else -> "LIBRARY"
57:             }
58:         }
59:     }
60:     return "MYSTERIOUS"
61: }
62: 
63: fun Settings.updateDefaultOpenTab(tab: String) {
64:     if (defaultOpenTab != tab) {
65:         defaultOpenTab = tab
66:         libraryFilter = LibraryFilterType.DEFAULT
67:     }
68: }
69: 
70: fun Settings.desktopSidebarNavItems(): List<NavItem> =
71:     try {
72:         sidebarNavItems.split(",").map { item ->
73:             val parts = item.split(":")
74:             NavItem(parts[0], parts[1].toBoolean())
75:         }
76:     } catch (_: Exception) {
77:         listOf(
78:             NavItem(NavigationId.HOME),
79:             NavItem(NavigationId.LIBRARY),
80:             NavItem(NavigationId.HISTORY),
81:             NavItem(NavigationId.STATISTICS),
82:             NavItem(NavigationId.LISTEN_TOGETHER),
83:         )
84:     }
85: 
86: fun Settings.desktopDefaultOpenTabs(): List<String> {
87:     val visibleIds = desktopSidebarNavItems().filter { it.visible }.map { it.id }
88:     return buildList {
89:         if (NavigationId.HOME in visibleIds) add("HOME")
90:         add("SEARCH")
91:         if (NavigationId.LIBRARY in visibleIds) addAll(libraryStartupTabs - "SONGS")
92:     }
93: }
94: 
95: fun Settings.desktopDefaultOpenTab(): String {
96:     val tabs = desktopDefaultOpenTabs()
97:     val current = defaultOpenTab.takeUnless { it == "SONGS" } ?: "LIBRARY"
98:     return current.takeIf { it in tabs } ?: tabs.first()
99: }
